head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods29000";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — contnId, index

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods29000.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_pageCount", fn: function(){ return ((dma_page.get("pageCount") ?? (() => { throw new Error("unresolved:" + "page.pageCount"); })())!==0); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 [0" + String(dma_sprtroomForm.get("pageIndex")) + "/" + String(dma_page.get("pageCount")) + " 페이지]"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const contnId = (String(((dma_pageContext.get("contnId") ?? "")) === null ? '' : ((dma_pageContext.get("contnId") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("contnId") ?? "")) === null ? '' : ((dma_pageContext.get("contnId") ?? ""))));
        const index = (String(((dma_pageContext.get("index") ?? "")) === null ? '' : ((dma_pageContext.get("index") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("index") ?? "")) === null ? '' : ((dma_pageContext.get("index") ?? ""))));
        if (contnId.length > 0) {
            scwin.detail(contnId, index, 'init');
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods29000.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldods29000: 진입 키 faq 는 알지만 그 URL 을 쓰는 tx 가 화면에 없다(URL 을 지어내지 않는다) · 자기 목록 tx 0

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name input_21_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.input_21_onclick = function(e){
    try {
        scwin.search(1)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods29000.input_21_onclick' }); }
};

/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_pageSize_onchange = function(e){
    try {
        scwin.search(1);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods29000.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name noticeTable_oncellclick
 * @description noticeTable 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.noticeTable_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_faqList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_faqList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.detail(r["sprtRoomNo"], r["index"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'noticeTable.oncellclick' });
    }
};

/**
 * @method
 * @name __on_enter_1_ipt_keyword
 * @description on enter 1 ipt keyword 처리
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.__on_enter_1_ipt_keyword = function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ scwin.search() }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods29000.__on_enter_1_ipt_keyword' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_55_onclick
 * @description krxpage_pagenavigator_55 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_55_onclick = function (index) {
    try {
    const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldods29000.krxpage_pagenavigator_55_onclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name detail
 * @description detail 처리
 * @param {*} ipt_sprtRoomNo ipt_sprtRoomNo
 * @param {Number} index index
 * @param {*} init init
 * @returns {void}
 * @hidden N
 */
scwin.detail = function (ipt_sprtRoomNo, index, init) {
    $('#ipt_sprtRoomNo', $('#searchForm')).val(ipt_sprtRoomNo);
    $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods29010/jldods29010.xml");
    $('#ipt_method', $('#searchForm')).val("readFaqDetail");
    $('#searchForm').submit();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @param {*} ipt_pageIndex ipt_pageIndex
 * @returns {void}
 * @hidden N
 */
scwin.search = function (ipt_pageIndex) {
    if (ipt_pageIndex) {
        $('#ipt_pageIndex', $('#searchForm')).val(ipt_pageIndex);
    }
    blockLoading();
    $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods29000/jldods29000.xml");
    $('#ipt_method', $('#searchForm')).val("readFaqList");
    $('#searchForm').submit();
};
